try{$expect($request('DELETE',$documents.'?id='.$docId)[0]===503&&$snapshot($graphTables)===$before,'HTTP retirement audit failure keeps original document active');}finally{$pdo->exec('DROP TRIGGER cf_contract_http_doc_audit');}
